"""Regression coverage for declaration evaluation in Maybe deciders."""

import unittest

import factory


class MaybeDeciderTests(unittest.TestCase):
    def test_faker_defaults_are_resolved_for_each_build(self):
        for chance, expected in [(0, 'no'), (100, 'yes')]:
            with self.subTest(chance=chance):
                class SampleFactory(factory.DictFactory):
                    value = factory.Maybe(
                        factory.Faker(
                            'pybool', locale='en_US',
                            truth_probability=factory.LazyFunction(lambda: chance),
                        ),
                        yes_declaration='yes',
                        no_declaration='no',
                    )

                self.assertEqual(
                    SampleFactory.build_batch(2),
                    [{'value': expected}] * 2,
                )

    def test_nested_maybe_decider(self):
        class SampleFactory(factory.DictFactory):
            value = factory.Maybe(
                factory.Maybe(factory.LazyFunction(lambda: True), True, False),
                yes_declaration='yes',
                no_declaration='no',
            )

        self.assertEqual(SampleFactory(), {'value': 'yes'})

    def test_overrides_go_to_selected_declaration(self):
        class SampleFactory(factory.DictFactory):
            value = factory.Maybe(
                factory.Faker('pybool', truth_probability=100),
                yes_declaration=factory.Faker('pyint', min_value=1, max_value=1),
                no_declaration=None,
            )

        self.assertEqual(
            SampleFactory(value__min_value=7, value__max_value=7),
            {'value': 7},
        )
